    const dip = `<tr><td colspan="6">Toplam · ${L.length} kredi</td><td class="para">${topPbH(L, 'anapara')}</td><td></td><td></td><td class="para">${topPbH(L, 'taksit')}</td><td></td><td></td><td class="para">${top(L, 'gecikenTaksit')} adet<small>${topPbH(L, 'gecikenTutar', true)}</small></td><td class="para">${topPbH(L, 'kalanAnapara')}</td><td class="para">${topPbH(L, 'kar')}</td><td class="para">${topPbH(L, 'bsmv')}</td><td class="para">${topPbH(L, 'gecikmeFaizi')}</td><td class="para">${topPbH(L, 'masraf')}</td><td class="para">${topPbH(L, 'oncesiToplamBorc')}</td><td></td><td></td></tr>`;
