      + s('Faiz Başlangıcı', h.faizBaslangic ? tarih(h.faizBaslangic) : '') + s('İşlemiş Faiz', h.islemisFaiz ? tutarPb(h.islemisFaiz, pb) : '') + s('Komisyon', h.komisyon ? tutarPb(h.komisyon, pb) : '') + s('BSMV + KKDF', h.bsmv ? tutarPb(h.bsmv, pb) : '') + s('KDV', h.kdv ? tutarPb(h.kdv, pb) : '') + s('Temerrüt Faizi', h.temerrutFaizi ? tutarPb(h.temerrutFaizi, pb) : '')
      + (pb !== 'TRY' ? s('Bakiye (Döviz)', tutarPb(h.bakiyeDoviz, pb)) + s('Kur', h.kur ? n0(h.kur).toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 4 }) : '') : '') + s('Bakiye ₺', tl(h.bakiye) + (od ? ' · mühlet tarihi bakiyesi · ödendi' : ''))
