    const l = e.target.closest('.ky-hb-l'); if (l) { e.stopPropagation(); if (tip === 'belge') { const b2 = V.belgeler.find(x => x.id === +l.dataset.id); if (b2) belgePencere('belge', b2); } else belgePencere(tip, k, +l.dataset.id); return; }
