    const rows = B.map(b => { const pb = b.pb || 'TRY'; return `<tr class="${b.taksitTuru === 'Masraf' ? 'soluk' : ''}" data-id="${b.id}"><td class="ad"><a href="#" class="ky-borc-duzenle" data-id="${b.id}" title="Düzenle">${esc(b.sirket)}</a></td><td>${esc(b.banka)}</td><td class="sayac">${b.siraNo || '—'}</td><td>${tarih(b.vade)}${b.vade && b.vade < bugun ? '<small>vadesi geçti</small>' : ''}</td><td>${rz(b.taksitTuru, b.taksitTuru === 'Proje' ? 'mavi' : 'gri')}</td><td class="metin">${esc(b.detayTuru || '—')}</td><td>${esc(b.ekNo || '—')}</td><td>${rz(pb, pb === 'TRY' ? 'gri' : 'mavi')}</td><td class="para">${tutarPb(b.anaPara, pb)}</td><td class="para">${n0(b.tahsilEdilen) ? tutarPb(b.tahsilEdilen, pb) : bos}</td><td class="para">${b.kalanAnaPara != null ? tutarPb(b.kalanAnaPara, pb) : `${tutarPb(bKalan(b), pb)}<small>hesaplanan</small>`}</td><td class="para">${bN(b.kalanAnaParaTl, 'TRY')}</td><td class="para">${tutarPb(b.kar, pb)}</td><td class="para">${tutarPb(b.bsmv, pb)}</td><td class="para genel">${bN(b.borc, pb)}</td><td class="para">${bN(b.tahsilTutari, pb)}</td><td class="para">${bN(b.tahsilTutariTl, 'TRY')}</td><td class="para">${bN(b.gecikmeCezasi, pb)}</td><td class="para">${bN(b.gecikmeCezasiTl, 'TRY')}</td><td class="para genel">${bN(b.toplamBorcTl, 'TRY')}</td><td><small class="ky-not" title="Tamamını görmek için tıklayın">${esc(b.kaynak || '')}</small></td><td class="metin"><small class="ky-not" title="Tamamını görmek için tıklayın">${esc(b.not || '')}</small></td><td><button type="button" class="btn btn-light border ky-borc-duzenle" data-id="${b.id}" title="Düzenle"><i class="fas fa-pen"></i></button> <button type="button" class="btn btn-light border text-danger ky-borc-sil" data-id="${b.id}" title="Satırı sil"><i class="fas fa-trash"></i></button></td></tr>`; });
