        `<td>${c.te.length || c.ce.length || c.bo.length ? `${c.te.length} rehin · ${c.ce.length} çek · ${c.bo.length} döküm` : bos}</td>` +
        `<td>${kontrolRz(dg)}</td><td class="metin"><small class="ky-not" title="Tamamını görmek için tıklayın">${esc(c.k.not || '')}</small></td>` +
        `<td>${c.k.tarih ? esc(c.k.tarih.slice(0, 10).split('-').reverse().join('.') + ' ' + c.k.tarih.slice(11)) + `<small>${esc(c.k.kullanici || '')}</small>` : bos}</td>` +
        `<td>${dugme('OK', 'fa-check', 'Tüm bilgiler yüklendi → OK', 'text-success')} ${dugme('Eksik', 'fa-triangle-exclamation', 'Eksik var (not istenir)', 'text-warning')} ${dugme('Bekliyor', 'fa-rotate-left', 'İşareti geri al (Bekliyor)')} ${dugme('not', 'fa-pen', 'Kontrol notu')}</td></tr>`;
