      const tk = plan.filter(p => p.tur !== 'Peşinat'), ps = plan.filter(p => p.tur === 'Peşinat'), toplam = tk.reduce((s, p) => s + n0(p.tutar), 0), pesinat = ps.reduce((s, p) => s + n0(p.tutar), 0);
