    const son = h.plan ? h.son : (ilk && h.n ? (() => { const t = new Date(ilk); t.setMonth(t.getMonth() + h.n - 1); return t.toISOString().slice(0, 10); })() : '');
    const yeniAna = h.plan && d.yeniAnapara <= 0 ? h.toplam : d.yeniAnapara;
