      ['Taksit Sayısı', h.n ? `${h.n}` : '—', h.plan ? `protokol planı · ${(d.odemePlani || []).filter(p => p.tur === 'Peşinat').length} peşinat satırı` : d.odemesizAy ? `${d.odemesizAy} ay ödemesiz` : 'ödemesiz dönem yok'],
      ['Hesaplanan Taksit', h.plan ? '—' : h.taksit ? P(h.taksit) : '—', h.plan ? 'planda faiz ayrımı yok' : `aylık oran ${(d.yeniFaizOrani / 12 * (1 + d.bsmvOrani / 100)).toLocaleString('tr-TR', { maximumFractionDigits: 4 })} % (BSMV dahil)`],
      ['Uygulanacak Taksit', h.uygulanan ? P(h.uygulanan) : '—', h.plan ? 'ilk taksit satırı (protokol)' : d.yeniTaksit > 0 ? 'banka protokolü tutarı' : 'hesaplanan tutar'],
      ['Aylık Fark', h.uygulanan ? `${h.uygulanan - d.taksit >= 0 ? '+' : ''}${P(h.uygulanan - d.taksit)}` : '—', `eski taksit ${P(d.taksit)}`],
      ['Toplam Geri Ödeme', h.genel ? P(h.genel) : '—', `${h.pesinat ? 'peşinat ' + P(h.pesinat) + ' · ' : ''}taksitler ${P(h.toplam)} · faiz ${P(h.faiz)} · anapara ${P(h.anapara)}${h.plan && Math.abs(h.toplam - yeniAna) > 0.05 ? ' · yeni anapara ' + P(yeniAna) + ' ile fark ' + P(h.toplam - yeniAna) : ''}${pb !== 'TRY' ? ' · TL karşılığı ≈ ' + tl(h.genel * (n0(d.kur) || n0(V.kurlar[pb]) || 1)) : ''}`],
      ['Borç Farkı · Teminat', h.genel ? `${h.genel - onceBorc >= 0 ? '+' : ''}${P(h.genel - onceBorc)}` : '—', `aktif teminat ${tl(teminat)} (${yeniAna > 0 && pb === 'TRY' ? yuzde(teminat / yeniAna * 100) : '—'})${ilk ? ' · ' + tarih(ilk) + (son ? ' – ' + tarih(son) : '') : ''}`]
